  return [{ json: { yt_found: false, yt_active: false, yt_account_id: '', yt_status: 'api_error', yt_username: '', contas: String(resp.error).substring(0, 200), total: 0 }, pairedItem: { item: 0 } }];
}
var raw = Array.isArray(resp.publishAccounts) ? resp.publishAccounts
  : Array.isArray(resp.accounts) ? resp.accounts
  : (resp.data && Array.isArray(resp.data.accounts)) ? resp.data.accounts
  : Array.isArray(resp.data) ? resp.data : [];
function isYouTube(a){ var p=String((a&&(a.platform||a.type||a.socialPlatform))||'').toLowerCase(); return p.indexOf('youtube')>=0 || p==='yt' || p.indexOf('shorts')>=0; }
function st(a){ return String((a&&(a.status||a.state||a.connectionStatus))||'').toLowerCase().trim(); }
var yts = raw.filter(isYouTube);
var active = yts.find(function(a){ return st(a)==='active'; });
var chosen = active || yts[0] || null;
var contas = raw.map(function(a){ return String((a&&(a.platform||a.type))||'?') + ':' + st(a); }).join(', ');
return [{ json: {
  yt_found: yts.length>0,
  yt_active: !!active,
  yt_account_id: active ? String(active.id||active.socialAccountId||active.socialId||'') : '',
  yt_status: chosen ? st(chosen) : 'not_found',
  yt_username: chosen ? (chosen.username||chosen.page||chosen.name||'') : '',
  contas: contas,
  total: raw.length
}, pairedItem: { item: 0 } }];

parameters.query:
SELECT COALESCE(EXTRACT(EPOCH FROM MAX(data_publicacao))::bigint, EXTRACT(EPOCH FROM NOW())::bigint) AS last_unix
FROM publicacoes
WHERE plataforma='youtube' AND status='agendado' AND data_publicacao > NOW();

parameters.jsCode:
var clips = $('get-clips-sem-youtube').all().map(function(i){ return i.json; });
if (!clips.length) return [];
var acct = $('pick-yt-account').first().json;
var ytId = String(acct.yt_account_id || '');
var ytName = String(acct.yt_username || '');
var lastUnix = Number($('get-last-yt-schedule').first().json.last_unix || 0);

var CAP_PER_DAY = 10;
var WIN_START_H = 8;
var WIN_END_H = 22;
var WIN_SPAN_S = (WIN_END_H - WIN_START_H) * 3600;

var byNicho = {};
for (var a=0; a<clips.length; a++){ var n=String(clips[a].nicho||'geral').toLowerCase(); (byNicho[n]=byNicho[n]||[]).push(clips[a]); }
var queues = Object.keys(byNicho).map(function(k){ return byNicho[k]; });
var ordered = [];
var go = true;
while (go){ go=false; for (var q=0; q<queues.length; q++){ if (queues[q].length){ ordered.push(queues[q].shift()); go=true; } } }

var nowSp = new Date(Date.now() - 3*3600*1000);
var baseY = nowSp.getUTCFullYear(), baseM = nowSp.getUTCMonth()+1, baseD = nowSp.getUTCDate()+1;
if (lastUnix > 0){
  var last = new Date(lastUnix*1000 - 3*3600*1000);
  var lastNext = Date.UTC(last.getUTCFullYear(), last.getUTCMonth(), last.getUTCDate()+1);
  var tom = Date.UTC(baseY, baseM-1, baseD);
  if (lastNext > tom){ var ln=new Date(lastNext); baseY=ln.getUTCFullYear(); baseM=ln.getUTCMonth()+1; baseD=ln.getUTCDate(); }
}
function ri(a,b){ return Math.floor(Math.random()*(b-a+1))+a; }

var out = [];
for (var i=0; i<ordered.length; i++){
  var c = ordered[i];
  var dayOffset = Math.floor(i / CAP_PER_DAY);
  var posInDay = i % CAP_PER_DAY;
  var t = new Date(Date.UTC(baseY, baseM-1, baseD + dayOffset));
  var y=t.getUTCFullYear(), m=t.getUTCMonth()+1, d=t.getUTCDate();
  var step = WIN_SPAN_S / CAP_PER_DAY;
  var secOfDay = WIN_START_H*3600 + Math.floor(posInDay*step) + ri(0,120);
  var publishMs = Date.UTC(y, m-1, d, 0,0,0) + (secOfDay + 3*3600)*1000;
  out.push({ json: {
    clip_id: c.id,
    finalVideoId: Number(c.vizard_video_id||0),
    title: String(c.titulo_final||'').substring(0,100),
    post: String(c.descricao_base||'').substring(0,5000),
    nicho: String(c.nicho||''),
    account_id: ytId,
    account_name: ytName,
    publish_time_ms: publishMs,
    publish_time_iso: new Date(publishMs).toISOString()
  }, pairedItem: { item: 0 } });
}
return out;

var payload = $('loop').item.json;
var res = $input.first().json || {};
var now = Math.floor(Date.now()/1000);
var ptSec = Math.floor(Number(payload.publish_time_ms||0)/1000);

var ok = false, code = null, err = null, pubId = null;
if (res.error) {
  var msg = String(res.error);
  var m = msg.match(/Vizard API error (-?\d+)/i);
  code = m ? Number(m[1]) : null;
  err = msg.substring(0, 500).replace(/'/g, '');
} else {
  code = Number(res.code);
  ok = code === 2000;
  if (ok) { pubId = (res.data && (res.data.id || res.data.videoId)) || null; }
  else { err = (code + ': ' + String(res.errMsg||res.message||'resposta inesperada')).substring(0,500).replace(/'/g,''); }
}
var scheduled = ok && ptSec > now + 60;
return [{ json: {
  clip_id: payload.clip_id,
  account_id: payload.account_id,
  account_name: payload.account_name,
  pub_status: ok ? (scheduled ? 'agendado' : 'publicado') : 'erro',
  pub_platform_id: pubId,
  publish_time_ms: payload.publish_time_ms,
  publish_error: err
}, pairedItem: { item: 0 } }];

var j = $json;
return [{ json: {
  ok: false,
  motivo: 'Conta YouTube nao esta active na Vizard',
  yt_status: j.yt_status,
  contas: j.contas,
  acao: 'Reconectar/ativar o canal YouTube na Vizard. status locked = limite de contas do plano; expired = reautenticar. Sem active a API nao publica.'
}, pairedItem: { item: 0 } }];

